// Open compiles a closed policy and starts one independent local run.
func Open(name string, input []byte, at float64) (*Run, error) {
	b, err := Definition(name)
	if err != nil {
		return nil, err
	}
	p, err := Compile(b)
	if err != nil {
		return nil, err
	}
	return p.New(input, at)
}
